={
  "model": "claude-sonnet-4-6",
  "max_tokens": 600,
  "messages": [
    {
      "role": "user",
      "content": "Write a LinkedIn Sponsored Content ad for JobFrank (jobfrank.app). Audience: people actively looking for jobs (Open to Work). Topic: {{ $json.topic }}.\n\nOutput a JSON object with exactly these fields:\n- headline: under 70 characters, punchy, speaks to pain of generic resumes\n- introText: 150-200 characters, practical and direct, no fluff\n- cta: one of: Apply Now, Learn More, Sign Up, Get Started\n- destinationUrl: https://jobfrank.app\n\nOutput only the JSON, no explanation."
    }
  ]
}

parameters.jsCode:
const raw = $input.first().json.content[0].text;
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('Claude did not return valid JSON: ' + raw);
const ad = JSON.parse(match[0]);
const params = $('Set Ad Parameters').first().json;
return [{ json: {
  headline: ad.headline,
  introText: ad.introText,
  cta: ad.cta,
  destinationUrl: ad.destinationUrl,
  dailyBudgetCents: params.dailyBudgetCents,
  durationDays: params.durationDays
}}];

const groupId = $env.LINKEDIN_CAMPAIGN_GROUP_ID;
const adData = $('Parse Ad Copy').first().json;

if (groupId) {
  return [{ json: { ...adData, campaignGroupUrn: 'urn:li:sponsoredCampaignGroup:' + groupId, skipGroupCreate: true } }];
}

return [{ json: { ...adData, skipGroupCreate: false } }];

const prev = $('Create Campaign Group if Needed').first().json;
let campaignGroupUrn = prev.campaignGroupUrn;

if (!campaignGroupUrn) {
  const created = $('Create Campaign Group').first().json;
  const id = created.id || (created.headers && created.headers['x-linkedin-id']);
  if (!id) throw new Error('Could not get campaign group ID from LinkedIn response: ' + JSON.stringify(created));
  campaignGroupUrn = 'urn:li:sponsoredCampaignGroup:' + id;
}

return [{ json: { ...prev, campaignGroupUrn } }];

